window.TP3B["camara:220655"] = [{"t":"PL","n":"3778","y":"2026","e":"Altera a Lei nº 7.960, de 21 de dezembro de 1989, para disciplinar prazo diferenciado da prisão temporária em investigações de organizações criminosas e associações criminosas de elevada complexidade, que demandem técnicas especiais de obtenção de prova.","d":"2026-07-17","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2026-09-04","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 05/09/2026.","id":"2640325","law":false,"r":"m"},{"t":"PDL","n":"477","y":"2026","e":"Susta, nos termos do art. 49, inciso V, da Constituição Federal, os efeitos do Decreto nº 12.975, de 20 de maio de 2026, que altera o Decreto nº 8.771, de 11 de maio de 2016, para dispor sobre os deveres dos provedores de conexão e de aplicações de internet.","d":"2026-05-26","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Apresentação de Proposição","u":"2026-05-26","ds":"Apresentação do PDL n. 477/2026 (Projeto de Decreto Legislativo), pelo Deputado Mario Frias (PL/SP), que \"Susta, nos termos do art. 49, inciso V, da Constituição Federal, os efeitos do Decreto nº 12.975, de 20 de maio de 2026, que altera o Decreto nº 8.771, de 11 de maio de 2016, para dispor sobre os deveres dos provedores de conexão e de aplicações de internet\".","id":"2627789","law":false,"r":"m"},{"t":"PDL","n":"396","y":"2026","e":"Susta os Decretos nºs 12.975/2026 e 12.976/2026, que que dispõem sobre a regulamentação do Marco Civil da Internet e sobre deveres das plataformas digitais em matéria de proteção das mulheres no ambiente digital, respectivamente, por extrapolarem os limites do poder regulamentar do Poder Executivo, violarem a reserva legal em matéria de liberdade de expressão e comunicação, e usurparem competência normativa do Congresso Nacional.","d":"2026-05-21","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Notificações","u":"2026-07-09","ds":"Deferido o Requerimento n. 3532/2026.","id":"2626867","law":false,"r":"c"},{"t":"PEC","n":"8","y":"2026","e":"Altera o art. 228 da Constituição Federal para admitir, em caráter excepcional, a redução da maioridade penal em casos de crimes hediondos e de crueldade extrema contra pessoas e animais.","d":"2026-05-11","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2026-08-12","ds":"Designado Relator, Dep. Mendonça Filho (PL-PE), para a PEC 32/2015, ao qual esta proposição está apensada.","id":"2623400","law":false,"r":"c"},{"t":"PDL","n":"255","y":"2026","e":"Susta a eficácia do inciso XL do Art. 9°-C do Anexo XXI da Portaria de Consolidação GM/MS n° 2, de 28 de setembro de 2017, incluído pela Portaria GM/MS n° 10.719, de 7 de abril de 2026, que dispõe sobre a composição do Comitê Técnico Nacional de Saúde LGBTIA+.","d":"2026-04-22","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Apresentação de Proposição","u":"2026-04-22","ds":"Apresentação do PDL n. 255/2026 (Projeto de Decreto Legislativo de Sustação de Atos Normativos do Poder Executivo), pelas Deputada Rosangela Moro (PL/SP) e outros, que \"Susta a eficácia do inciso XL do Art. 9°-C do Anexo XXI da Portaria de Consolidação GM/MS n° 2, de 28 de setembro de 2017, incluído pela Portaria GM/MS n° 10.719, de 7 de abril de 2026, que dispõe sobre a composição do Comitê Técni","id":"2617450","law":false,"r":"c"},{"t":"PL","n":"1825","y":"2026","e":"Altera a Lei nº 15.211, de 17 de setembro de 2025 (Estatuto Digital da Criança e do Adolescente), para vedar mecanismos de censura prévia, assegurar a liberdade de expressão, preservar a livre iniciativa e garantir o devido processo legal.","d":"2026-04-14","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Notificação de Apensação","u":"2026-07-03","ds":"Apensação do PL 2306/2026 a esta proposição.","id":"2616025","law":false,"r":"m"},{"t":"PL","n":"824","y":"2026","e":"Dispõe sobre a proteção dos direitos fundamentais das mulheres, das crianças e das minorias, bem como da vedação à promoção e aplicação do conjunto de normas e práticas que compõe o que é conhecido como lei da Sharia no território nacional.","d":"2026-03-02","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Autorização)","tr":"Notificações","u":"2026-07-07","ds":"Deferido o Requerimento n. 2583/2026.","id":"2605433","law":false,"r":"c"},{"t":"PEC","n":"3","y":"2026","e":"Altera o art. 155 da Constituição Federal para estabelecer alíquota máxima e base de cálculo exclusiva do Imposto sobre a Propriedade de Veículos Automotores – IPVA, e acrescenta dispositivos ao Ato das Disposições Constitucionais Transitórias para limitar despesas com publicidade institucional e com o Poder Legislativo.","d":"2026-02-24","o":"in_progress","s":"Aguardando Criação de Comissão Temporária","tr":"Notificações","u":"2026-07-20","ds":"Indeferido o Requerimento n. 3829/2026.","id":"2604173","law":false,"r":"c"},{"t":"PL","n":"383","y":"2026","e":"Institui a disciplina Educação em Proteção e Direitos dos Animais como conteúdo obrigatório na educação básica; dispõe sobre a punição para crimes de maus-tratos a animais, tornando-os hediondos e imprescritíveis; estabelece a perda da guarda e tutela ao condenado; dispõe sobre o atendimento público à saúde animal e o controle populacional por meio de esterilização gratuita e cria o Cadastro Nacional de Pessoas Condenadas por Crimes Contra Animais.","d":"2026-02-06","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-03-20","ds":"Designado Relator, Dep. Túlio Gadêlha (REDE-PE).","id":"2601275","law":false,"r":"m"},{"t":"PLP","n":"238","y":"2025","e":"Dispõe sobre a vedação de critérios temporais ou artificiais no cálculo do Imposto Predial e Territorial Urbano – IPTU que resultem em desigualdade de tratamento entre imóveis de idêntico valor venal, padrão construtivo e localização, e assegura a restituição dos valores pagos a maior.","d":"2025-11-06","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Apresentação de Proposição","u":"2025-11-06","ds":"Apresentação do PLP n. 238/2025 (Projeto de Lei Complementar), pelos Deputado José Medeiros (PL/MT) e outros, que \"Dispõe sobre a vedação de critérios temporais ou artificiais no cálculo do Imposto Predial e Territorial Urbano – IPTU que resultem em desigualdade de tratamento entre imóveis de idêntico valor venal, padrão construtivo e localização, e assegura a restituição dos valores pagos a maior","id":"2582475","law":false,"r":"c"},{"t":"PL","n":"5728","y":"2025","e":"Dispõe sobre a possibilidade de substituição da contribuição previdenciária ao Regime Geral de Previdência Social por investimento equivalente em ativos financeiros e imóveis, e dá outras providências.","d":"2025-11-06","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2026-02-02","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 03/02/2026.","id":"2582474","law":false,"r":"c"},{"t":"PL","n":"5727","y":"2025","e":"Dispõe sobre a limitação de variações tributárias decorrentes de alteração de código da Classificação Nacional de Atividades Econômicas (CNAE) no objeto social de empresas.","d":"2025-11-06","o":"in_progress","s":"Aguardando Parecer","tr":"Encerramento de Prazo","u":"2026-06-03","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao projeto (de 22/05/2026 a 03/06/2026). Não foram apresentadas emendas.","id":"2582473","law":false,"r":"c"},{"t":"PEC","n":"40","y":"2025","e":"Altera o Art. 7° da Constituição Federal para prever a possibilidade de opção pelos empregados quanto à jornada de trabalho, podendo escolher entre o regime comum previsto pela Consolidação das Leis do Trabalho (CLT), ou um regime flexível baseado em horas trabalhadas.","d":"2025-10-29","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Apresentação de Requerimento","u":"2026-02-25","ds":"Apresentação do REQ n. 3/2026 (Requerimento de Audiência Pública), pelo Deputado Domingos Sávio (PL/MG), que \"Requer realização de audiência pública acerca da redução da jornada de trabalho, conforme proposta nas PECs nº 40/2025 e nº 8/2025\".","id":"2578996","law":false,"r":"c"},{"t":"PL","n":"5434","y":"2025","e":"Institui o Programa Nacional de Reconhecimento e Mérito Operacional das Forças de Segurança Pública, destinado a valorizar e incentivar atos de bravura, eficiência, excelência técnica e dedicação exemplar no combate à criminalidade e na proteção da sociedade, e dá outras providências.","d":"2025-10-28","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2026-02-02","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 03/02/2026.","id":"2577282","law":false,"r":"c"},{"t":"PL","n":"4823","y":"2025","e":"Institui, em âmbito nacional, o Sistema de Alerta Infantil Imediato (SAII) para difusão célere de informações sobre crianças e adolescentes desaparecidos em risco, e para recebimento e encaminhamento de denúncias de aliciamento infantil em ambientes digitais, por meio das redes de telefonia celular, plataformas digitais e meios oficiais, e dá outras providências.","d":"2025-09-30","o":"in_progress","s":"Aguardando Parecer","tr":"Devolução ao(à) Relator(a)","u":"2026-06-10","ds":"Devolvido ao Relator, Dep. Julio Cesar Ribeiro (REPUBLIC-DF), em virtude da apensação do PL 1650/2026.","id":"2565464","law":false,"r":"m"},{"t":"PL","n":"4631","y":"2025","e":"Altera a Lei nº 10.826, de 22 de dezembro de 2003, para assegurar o porte de arma de fogo para os Auditores Fiscais Federais Agropecuários e Técnicos em Fiscalização Federal Agropecuária.","d":"2025-09-17","o":"in_progress","s":"Tramitando em Conjunto","tr":"Apresentação de Requerimento","u":"2026-02-04","ds":"Apresentação do REQ n. 189/2026 (Requerimento de Desapensação), pelo Deputado Capitão Alden (PL/BA), que \"Requer a desapensação do Projeto de Lei nº 4.631, de 2025, que tramita conjuntamente com o Projeto de Lei nº 6.070, de 2016\".","id":"2561808","law":false,"r":"c"},{"t":"PEC","n":"32","y":"2025","e":"Esta Lei altera o artigo 5º, inciso XLIII, da Constituição Federal, o qual prevê que nos casos de crimes previstos neste inciso, a pena deverá ser cumprida integralmente em regime fechado, por eles respondendo os mandantes, os executores e os que, podendo evitá-los, se omitirem, e dá outras providências.","d":"2025-08-20","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Aprovação de Requerimento","u":"2026-09-01","ds":"Aprovado o requerimento nº 1/2026,da Sra. Talíria Petrone que requer a realização de Audiência Pública no âmbito da Comissão Especial sobre a redução da maioridade penal (PEC 32/2015) para debater a idade penal como cláusula pétrea e o controle de constitucionalidade da redução frente aos direitos e garantias individuais imutáveis da Constituição de 1988, sugerindo os seguintes especialistas: Dr. ","id":"2551011","law":false,"r":"c"},{"t":"PL","n":"3798","y":"2025","e":"Dispõe sobre vedações à atuação de magistrados no exercício da função jurisdicional, com o objetivo de preservar os princípios constitucionais do devido processo legal, imparcialidade, juiz natural, liberdade de expressão e separação de Poderes.","d":"2025-08-06","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Autorização)","tr":"Apresentação de Proposição","u":"2025-08-06","ds":"Apresentação do PL n. 3798/2025 (Projeto de Lei), pelos Deputado Rodrigo da Zaeli (PL/MT) e outros, que \"Dispõe sobre vedações à atuação de magistrados no exercício da função jurisdicional, com o objetivo de preservar os princípios constitucionais do devido processo legal, imparcialidade, juiz natural, liberdade de expressão e separação de Poderes\n\".","id":"2541173","law":false,"r":"c"},{"t":"PDL","n":"358","y":"2025","e":"Susta os efeitos do Decreto nº 12.534, de 25 de junho de 2025, que altera regras de acesso ao Benefício de Prestação Continuada (BPC).","d":"2025-06-30","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Notificações","u":"2025-07-18","ds":"Deferido o REQ 2468/2025.","id":"2529430","law":false,"r":"c"},{"t":"PLP","n":"136","y":"2025","e":"Altera a Lei Complementar nº 210, de 25 de novembro de 2024, para vedar a dedução de valores das transferências oriundas de emendas parlamentares para custeio de despesas administrativas pelo Poder Executivo.","d":"2025-06-18","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2025-10-10","ds":"Recebimento pelo(a) CFT.","id":"2527265","law":false,"r":"c"},{"t":"PDL","n":"338","y":"2025","e":"Susta a Portaria, nº 45 de 16 de maio de 2025, que Dispõe sobre a dedução de percentual das transferências financeiras ao ente ou entidade beneficiária, financiadas por recursos de emenda parlamentar, para custear os serviços para a operacionalização da execução dos projetos e das atividades de fiscalização exercidas diretamente pelos órgãos do Ministério do Esporte","d":"2025-06-16","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Apresentação de Proposição","u":"2025-06-16","ds":"Apresentação do PDL n. 338/2025 (Projeto de Decreto Legislativo), pelo Deputado Mario Frias (PL/SP), que \"Susta a Portaria, nº 45 de 16 de maio de 2025, que Dispõe sobre a dedução de percentual das transferências financeiras ao ente ou entidade beneficiária, financiadas por recursos de emenda parlamentar, para custear os serviços para a operacionalização da execução dos projetos e das atividades d","id":"2525863","law":false,"r":"m"},{"t":"PDL","n":"228","y":"2025","e":"Susta, nos termos do art. 49, V, da Constituição Federal, os efeitos do Decreto nº 12.467, de 23 de maio de 2025.","d":"2025-05-26","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados","tr":"Apresentação de Requerimento","u":"2025-06-25","ds":"Apresentação do REQ n. 2398/2025 (Requerimento de Apensação), pelo Deputado Zucco (PL/RS), que \"Requer a apensação dos projetos que especifica ao Projeto de Decreto Legislativo n. 214/2025\".","id":"2516046","law":false,"r":"m"},{"t":"PDL","n":"217","y":"2025","e":"Susta, nos termos do art. 49, V, da Constituição Federal, os efeitos do Decreto nº 12.467, de 23 de maio de 2025.","d":"2025-05-23","o":"prejudged","s":"Arquivada","tr":"Desapensação","u":"2025-06-25","ds":"Desapensação deste do PDL nº 214, de 2025, principal, em face da aprovação, em Plenário, do Substitutivo ao Projeto de Decreto Legislativo nº 214, de 2025, adotado pelo relator da Comissão de Constituição e Justiça e de Cidadania. (Sessão Deliberativa Extraordinária Semipresencial de 25/06/2025 - 13:55 - 111ª Sessão)","id":"2515691","law":false,"r":"m"},{"t":"PL","n":"2265","y":"2025","e":"Revoga os arts. 359-L e 359-M do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 – Código Penal Brasileiro.","d":"2025-05-13","o":"approved_with_another_bill","s":"Arquivada","tr":"Prejudicialidade (Plenário)","u":"2025-12-09","ds":"Matéria aprovada na forma do Substitutivo ao Projeto de Lei nº 2.162, de 2023, adotado pelo relator da Comissão Especial (Sessão Deliberativa Extraordinária Presencial de 09/12/2025 - 19:00 - 278ª Sessão). Esta proposição fica prejudicada, na forma do art. 191 do RICD.","id":"2508216","law":false,"r":"c"},{"t":"PEC","n":"17","y":"2025","e":"Acrescenta os §§ 11, 12 e 13 ao art. 144 da Constituição Federal, para instituir o piso salarial dos servidores policiais civis e militares e bombeiros militares.","d":"2025-04-23","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Relatório de Conferência de Assinaturas","u":"2025-04-23","ds":"Relatório de Conferência de Assinaturas Eletrônicas.","id":"2499794","law":false,"r":"c"},{"t":"PL","n":"1792","y":"2025","e":"Reconhece ao paciente Renal Crônico, o mesmo tratamento legal e os mesmos direitos garantidos às pessoas com deficiência, e dá outras providências.","d":"2025-04-22","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2026-03-25","ds":"Parecer da Relatora, Dep. Rogéria Santos (REPUBLIC-BA), pela aprovação, com substitutivo.","id":"2499052","law":false,"r":"m"},{"t":"PL","n":"1316","y":"2025","e":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal) e o Decreto-Lei nº 3.689, de 3 de outubro de 1941 (Código de Processo Penal), para proibir a oferta de Acordo de Não Persecução Penal aos crimes de corrupção ativa e corrupção passiva, e dá outras providências.","d":"2025-03-31","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Notificações","u":"2025-06-11","ds":"Deferido o REQ 1271/2025.","id":"2491061","law":false,"r":"c"},{"t":"PDL","n":"120","y":"2025","e":"Susta a Portaria MinC nº 64, de 28 de setembro de 2023, que institui o Programa Nacional dos Comitês de Cultura.","d":"2025-03-12","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2026-07-07","ds":"Parecer da Relatora, Dep. Jandira Feghali (PCdoB-RJ), pela rejeição.","id":"2486555","law":false,"r":"c"},{"t":"PDL","n":"118","y":"2025","e":"Susta a Portaria MAPA/SDA nº 1179, de 05 setembro de 2024.","d":"2025-03-11","o":"archived_reason_not_stated","s":"Arquivada","tr":"Arquivamento","u":"2025-11-13","ds":"Arquivado","id":"2486245","law":false,"r":"c"},{"t":"PEC","n":"9","y":"2025","e":"Acrescenta o § 16 ao art. 198 da Constituição Federal, para dispor sobre as diretrizes para os Planos de Carreira e os pisos salariais nacionais dos profissionais de saúde do Sistema Único de Saúde.","d":"2025-02-27","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-06-10","ds":"Designado Relator, Dep. Coronel Assis (PL-MT).","id":"2485767","law":false,"r":"c"},{"t":"PL","n":"385","y":"2025","e":"Altera a Lei altera a Lei nº 7.210, de 11 de julho de 1984 (Lei de Execução Penal), para dispor sobre a proibição de atividades comerciais dentro dos estabelecimentos penais.","d":"2025-02-11","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2025-08-19","ds":"Recebimento pela CCJC.","id":"2483604","law":false,"r":"c"},{"t":"PL","n":"117","y":"2025","e":"Altera a Lei nº 12.527, de 18 de novembro de 2011, para considerar de interesse público as informações relativas ao exercício de atividades representativas pelo cônjuge de Presidente da República, de Governador de Estado, de Governador do Distrito Federal e de Prefeito.","d":"2025-02-03","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2025-08-06","ds":"Designado Relator, Dep. Pastor Sargento Isidório (AVANTE-BA), para o PL 104/2025, ao qual esta proposição está apensada.","id":"2482427","law":false,"r":"c"},{"t":"PL","n":"10","y":"2025","e":"Dispõe sobre a criminalização de condutas atentatórias contra o Cristianismo e estabelece a reparação por dano moral objetivo à imagem do Cristianismo em caso de ofensa pública às religiões de matriz cristã, e dá outras providências.","d":"2025-02-03","o":"status_not_published","s":"","tr":"Notificações","u":"2025-11-10","ds":"Devolvido ao Relator, Dep. Pr. Marco Feliciano (PL-SP), para o PL 1804/2015, ao qual esta proposição está apensada.","id":"2482103","law":false,"r":"c"},{"t":"PDL","n":"27","y":"2025","e":"Susta nos termos do art. 49, V e X, da Constituição Federal  o artigo 38 do Decreto nº 11.615, de 21 de julho de 2023, aonde restringe o funcionamento dos clubes de tiro ao horário das 18h às 22h, alterado pelo Decreto 12.345 de 30 de dezembro de 2024.","d":"2025-02-03","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2025-04-14","ds":"Devolvido ao Relator, Dep. Delegado Paulo Bilynskyj (PL-SP), para o PDL 3/2023, ao qual esta proposição está apensada.","id":"2482263","law":false,"r":"c"},{"t":"PDL","n":"26","y":"2025","e":"Susta a Instrução Normativa da Receita Federal do Brasil n.º 2.219, de 17 de setembro de 2024, que “dispõe sobre a obrigatoriedade de prestação de informações relativas às operações financeiras de interesse da Secretaria Especial da Receita Federal do Brasil na e-Financeira.”","d":"2025-02-03","o":"archived_reason_not_stated","s":"Arquivada","tr":"Arquivamento","u":"2025-03-20","ds":"Arquivado","id":"2482262","law":false,"r":"c"},{"t":"PDL","n":"25","y":"2025","e":"Susta a Resolução Conanda nº 258, de 23 de dezembro de 2024, que dispõe sobre o atendimento de crianças e adolescentes vítimas de violência sexual e a garantia dos seus direitos","d":"2025-02-03","o":"prejudged","s":"Arquivada","tr":"Desapensação","u":"2025-11-05","ds":"Desapensação deste do PDL nº 3, de 2025, principal, em face da aprovação, em Plenário, do Projeto de Decreto Legislativo nº 3, de 2025. (Sessão Deliberativa Extraordinária Semipresencial de 05/11/2025 - 10:00 - 241ª Sessão)","id":"2482261","law":false,"r":"c"},{"t":"PDL","n":"24","y":"2025","e":"Susta o Decreto nº 12.341, de 23 de dezembro de 2024, que Regulamenta a Lei nº 13.060, de 22 de dezembro de 2014, para disciplinar o uso da força e dos instrumentos de menor potencial ofensivo pelos profissionais de segurança pública.","d":"2025-02-03","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2025-11-10","ds":"Recebimento pela CCJC, apensado ao PDL-5/2025","id":"2482260","law":false,"r":"c"},{"t":"PEC","n":"51","y":"2024","e":"Altera o art. 7º e o Ato das Disposições Constitucionais Transitórias da Constituição Federal de 1988, para dispor sobre as condições especiais de trabalho do motorista profissional empregado no transporte rodoviário de cargas e de passageiros.","d":"2024-12-12","o":"in_progress","s":"Aguardando Criação de Comissão Temporária","tr":"Publicação de Proposição","u":"2025-11-13","ds":"Encaminhada à publicação. Parecer da Comissão de Constituição e Justiça e de Cidadania Publicado em avulso e no DCD de 14/11/2025, Letra A.","id":"2479738","law":false,"r":"c"},{"t":"PEC","n":"44","y":"2024","e":"Altera o §9º do artigo 166 da Constituição Federal para destinar parte dos recursos oriundos das emendas individuais a programas e ações relacionados ao Esporte.","d":"2024-11-26","o":"in_progress","s":"Aguardando Criação de Comissão Temporária","tr":"Apresentação de Requerimento","u":"2025-11-07","ds":"Apresentação do REQ n. 4717/2025 (Requerimento de Inclusão ou Retirada de Assinatura em Proposição de Iniciativa Coletiva Obrigatória), pelo Deputado Carlos Sampaio (PSD/SP -Fdr PSDB-CIDADANIA), que \"Requer a inclusão de assinatura na PEC n. 44/2024\".","id":"2471383","law":false,"r":"c"},{"t":"PLP","n":"177","y":"2024","e":"Revoga a Lei Complementar n.º 207, de 17 de maio de 2024.","d":"2024-10-31","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-02-24","ds":"Designado Relator, Dep. Geraldo Mendes (UNIÃO-PR).","id":"2466470","law":false,"r":"c"},{"t":"PL","n":"4112","y":"2024","e":"Altera a parte geral do Código Penal Brasileiro, inserindo o Artigo 13-A, estabelecendo que, em caso de reincidência, a pena será, no mínimo, o dobro da pena prevista para o crime de origem, e da outras providências.","d":"2024-10-29","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2024-12-19","ds":"Designado Relator, Dep. Nikolas Ferreira (PL-MG)","id":"2465101","law":false,"r":"m"},{"t":"PL","n":"3353","y":"2024","e":"Dispõe sobre o prazo de validade do laudo médico que ateste o Diabetes Mellitus - Tipo 1 (DM1) no âmbito da República Federativa do Brasil, e estabelece outras providências","d":"2024-08-28","o":"prejudged","s":"Arquivada","tr":"Desapensação","u":"2025-10-21","ds":"Desapensação deste do PL nº 3.472, de 2023, principal, em face da aprovação, em Plenário, do Substitutivo ao Projeto de Lei nº 3.472, de 2023, adotado pelo relator da Comissão de Saúde. . (Sessão Deliberativa Extraordinária Presencial de 21/10/2025 - 13:55 - 227ª Sessão)","id":"2455794","law":false,"r":"m"},{"t":"PDL","n":"333","y":"2024","e":"Susta a resolução CSDPU nº 222 de 1º de agosto de 2024 para provimento de cargos de Defensor Público Federal com reserva de 2% de vagas para pessoas trans e travestis em concursos públicos.","d":"2024-08-13","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2025-03-24","ds":"Recebimento pela CDHMIR.","id":"2452318","law":false,"r":"c"},{"t":"PL","n":"3070","y":"2024","e":"Propõe a reestruturação dos acervos bibliográficos pautados no princípio da pluralidade de ideias, conceitos, teorias e interpretações.","d":"2024-08-07","o":"in_progress","s":"Pronta para Pauta","tr":"Encerramento de Prazo","u":"2025-07-09","ds":"Prazo de Vista Encerrado","id":"2451280","law":false,"r":"m"},{"t":"PL","n":"2860","y":"2024","e":"Institui a cobrança de multa pelo porte e uso de entorpecentes em ambientes públicos.","d":"2024-07-11","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2025-10-22","ds":"Recebimento pela CFT, apensado ao PL-2771/2024","id":"2448942","law":false,"r":"c"},{"t":"PEC","n":"29","y":"2024","e":"Altera a Constituição Federal para acrescentar no art. 5º texto sobre o marco temporal de início da vida humana explicitando de forma inequívoca a inviolabilidade do direito à vida, desde a sua concepção, bem como cria o inciso LXXX para especificar que a concepção é a junção do gameta masculino e o feminino, ocorrida durante a fecundação, em local propício para o desenvolvimento celular.","d":"2024-07-10","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Relatório de Conferência de Assinaturas","u":"2024-07-10","ds":"Relatório de Conferência de Assinaturas Eletrônicas.","id":"2448752","law":false,"r":"c"},{"t":"PL","n":"2786","y":"2024","e":"Institui o Dia Nacional dos Presos Políticos.","d":"2024-07-09","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Notificações","u":"2024-10-16","ds":"Deferido o Requerimento nº 3819/2024.","id":"2447559","law":false,"r":"c"},{"t":"PEC","n":"24","y":"2024","e":"Altera os §§ 4º, 4°-B e 7º do art. 40 da Constituição Federal e os artigos 5º, 10, 23, 24 e 26 da Emenda Constitucional nº 103, de 2019, acrescenta o art. 144-A a Constituição e dá outras providências.","d":"2024-06-24","o":"in_progress","s":"Aguardando Constituição de Comissão Temporária","tr":"Expedição de Documento","u":"2026-08-26","ds":"Ato da Presidência: Cria Comissão Especial, nos termos do § 2º do art. 202 do Regimento Interno. Publicado em DCD Extra no dia 26/08/2026.","id":"2442880","law":false,"r":"c"},{"t":"PL","n":"2499","y":"2024","e":"Dispõe sobre a obrigatoriedade da notificação à autoridade policial, pelos hospitais, clínicas e unidades básicas de saúde, da interrupção de gestação decorrente de estupro e dá outras providências.","d":"2024-06-19","o":"in_progress","s":"Aguardando Parecer","tr":"Encerramento de Prazo","u":"2024-09-18","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao projeto (de 30/08/2024 a 18/09/2024). Não foram apresentadas emendas.","id":"2442393","law":false,"r":"c"},{"t":"PL","n":"2446","y":"2024","e":"Institui a política nacional de atenção dedicada ao cuidado e à saúde do homem, relacionada à deficiência androgênica do envelhecimento masculino e à disfunção erétil no âmbito do Sistema Único de Saúde do Governo Federal – SUS.","d":"2024-06-18","o":"in_progress","s":"Pronta para Pauta","tr":"Encerramento de Prazo","u":"2026-10-13","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao substitutivo (de 14/08/2026 a 13/10/2026). Não foram apresentadas emendas ao substitutivo.","id":"2441586","law":false,"r":"m"},{"t":"PL","n":"2388","y":"2024","e":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal) e a Lei nº 7.210, de 11 de julho de 1984 (Lei de Execução Penal), para estabelecer punições mais severas aos crimes de estupro e estupro de vulnerável.","d":"2024-06-13","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificação de Apensação","u":"2026-05-26","ds":"Apense-se a este o PL 1682/2026","id":"2440784","law":false,"r":"c"},{"t":"PDL","n":"301","y":"2024","e":"Susta o Decreto nº 12.032, de 28 de maio de 2024, que exclui a Empresa Gestora de Ativos S. A. - Emgea do Programa Nacional de Desestatização e revoga sua qualificação no âmbito do Programa de Parcerias e Investimentos da Presidência da República.","d":"2024-06-03","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2025-08-11","ds":"Recebimento pela CCJC, apensado ao PDL-299/2024","id":"2437509","law":false,"r":"c"},{"t":"PL","n":"2058","y":"2024","e":"Cria a Lei de Criminalização do Revenge Porn e Sextorsão.","d":"2024-05-27","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2025-10-08","ds":"Recebimento pela CCJC.","id":"2436529","law":false,"r":"c"},{"t":"PL","n":"1968","y":"2024","e":"Dispõe sobre a prorrogação do prazo da entrega da declaração de ajuste do imposto de renda no ano de 2024, referente ao ano fiscal de 2023, para os residentes do Estado do Rio Grande do Sul","d":"2024-05-21","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Análise)","tr":"Apresentação de Proposição","u":"2024-05-21","ds":"Apresentação do PL n. 1968/2024 (Projeto de Lei), pelo Deputado Kim Kataguiri (UNIÃO/SP) e outros, que \"Dispõe sobre a prorrogação do prazo da entrega da declaração de ajuste do imposto de renda no ano de 2024, referente ao ano fiscal de 2023, para os residentes do Estado do Rio Grande do Sul\".","id":"2435230","law":false,"r":"c"},{"t":"PL","n":"1904","y":"2024","e":"Acresce dois parágrafos ao art. 124, um parágrafo único ao artigo 125, um segundo parágrafo ao artigo 126 e um parágrafo único ao artigo 128, todos do Código Penal Brasileiro, e dá outras providências.","d":"2024-05-17","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Aprovação de Requerimento","u":"2024-08-14","ds":"Aprovado o requerimento nº 44/2024,da Sra. Chris Tonietto que requer a realização de Audiência Pública para debater sobre o PL 1904/2024, que acresce dois parágrafos ao art. 124, um parágrafo único ao artigo 125, um segundo parágrafo ao artigo 126 e um parágrafo único ao artigo 128, todos do Código Penal Brasileiro, e dá outras providências.","id":"2434493","law":false,"r":"c"},{"t":"PEC","n":"17","y":"2024","e":"Acrescenta art. 132-A e altera o art. 168 da Constituição Federal, para conferir autonomia orçamentária às Procuradorias dos Estados e do Distrito Federal e à Advocacia-Geral da União e seus órgãos vinculados.","d":"2024-05-13","o":"in_progress","s":"Aguardando Criação de Comissão Temporária","tr":"Distribuição","u":"2026-08-26","ds":"Defiro o Requerimento n. 4.079/2026, nos termos do art. 142, caput, do Regimento Interno da Câmara dos Deputados. Apense-se, pois, a Proposta de Emenda à Constituição n. 17/2024 à Proposta de Emenda à Constituição n. 82/2007. Publique-se.","id":"2432987","law":false,"r":"c"},{"t":"PL","n":"1721","y":"2024","e":"Altera a Lei nº 7.474, de 8 de maio de 1986, que dispõe sobre medidas de segurança aos ex-Presidentes da República, e dá outras providências.","d":"2024-05-09","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2024-05-21","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 22/05/2024 PAG 1161","id":"2432717","law":false,"r":"c"},{"t":"PL","n":"1633","y":"2024","e":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 - Código Penal para considerar como crime a criação de óbice ou embaraço fiscal, sanitário, ambiental ou administrativo, oimpedimento ou dificuldade ao serviço de combate ao perigo, de socorro ou salvamento, ou a entregade donativos ou o resgate às vítimas, durante a vigência de estado de calamidade pública.","d":"2024-05-07","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2024-05-13","ds":"Recebimento pela CCJC.","id":"2431790","law":false,"r":"c"},{"t":"PL","n":"1571","y":"2024","e":"Institui o programa emergencial de incentivo a donativos e voluntariado para situações de emergência e calamidade pública, altera as leis n. 6.437, de 20 de agosto de 1977, 8.137, de 27 de dezembro de 1990,  8.234, de 17 de setembro de 1991, 9.537, de 11 de dezembro de 1997 e dá outras providências.","d":"2024-05-06","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2025-12-08","ds":"Recebimento pela CFT, com as proposições PL-1577/2024, PL-1718/2024 apensadas.","id":"2431054","law":false,"r":"c"},{"t":"PL","n":"1565","y":"2024","e":"Dispõe sobre a suspensão de exigências de pagamentos de tributos federais, durante o período de dois anos, para fatos geradores ocorridos exclusivamente no estado do Rio Grande do Sul.","d":"2024-05-06","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Análise)","tr":"Notificações","u":"2024-05-15","ds":"Deferido o Requerimento nº 1585/2024.","id":"2431027","law":false,"r":"c"},{"t":"PL","n":"1564","y":"2024","e":"Dispõe sobre medidas emergenciais para atenuar os efeitos da crise decorrente de desastres naturais nos setores de turismo e de cultura do Estado do Rio Grande do Sul.\n\nNOVA EMENTA: Dispõe sobre medidas emergenciais destinadas aos setores de turismo e de cultura do Estado do Rio Grande do Sul.","d":"2024-05-06","o":"approved","s":"Transformado em Norma Jurídica","tr":"Transformação em Norma Jurídica","u":"2024-07-05","ds":"Transformado na Lei Ordinária 14917/2024. DOU 08/07/24 PÁG 01 COL 02.","id":"2431026","law":true,"r":"c"},{"t":"PL","n":"1563","y":"2024","e":"Dispõe sobre a dedução de doações no imposto sobre a renda das doações efetuadas para a assistência às pessoas afetadas e a recuperação de danos decorrentes das enchentes no estado do Rio Grande do Sul em 2024.","d":"2024-05-06","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Análise)","tr":"Notificações","u":"2024-05-15","ds":"Deferido o Requerimento nº 1588/2024.","id":"2431025","law":false,"r":"c"},{"t":"PDL","n":"224","y":"2024","e":"Susta o Decreto n.º 11.995, de 15 de abril de 2024, que institui o Programa Terra da Gente e dispõe sobre a incorporação de imóveis rurais no âmbito da Política Nacional de Reforma Agrária.","d":"2024-04-29","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2025-04-14","ds":"Designado Relator, Dep. Nikolas Ferreira (PL-MG), para o PDL 167/2024, ao qual esta proposição está apensada.","id":"2430387","law":false,"r":"c"},{"t":"PDL","n":"108","y":"2024","e":"Susta parcialmente os efeitos da Resolução n. 391, de 10 de maio de 2021, do Conselho Nacional de Justiça, que \"estabelece procedimentos e diretrizes a serem observados pelo Poder Judiciário para o reconhecimento do direito à remição de pena por meio de práticas sociais educativas em unidades de privação de liberdade\".","d":"2024-04-02","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2024-04-19","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 20/04/2024.","id":"2424406","law":false,"r":"c"},{"t":"PL","n":"775","y":"2024","e":"Declara Amácio Mazzaropi Patrono do Cinema Brasileiro","d":"2024-03-14","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2024-03-25","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 26/03/DCD de 26/03/2024 PAG 202","id":"2421261","law":false,"r":"m"},{"t":"PL","n":"719","y":"2024","e":"Dispõe sobre a prorrogação do prazo de incentivos da Política Industrial Para o Setor de Tecnologias da Informação e Comunicação e para o Setor de Semicondutores, estabelecida pelas Leis nº 11.484, de 31 de maio de 2007 e Lei nº 8.248, de 23 de outubro de 1991, com as alterações da Lei nº 13.969, de 26 de dezembro de 2019.","d":"2024-03-12","o":"prejudged","s":"Arquivada","tr":"Desapensação","u":"2024-06-19","ds":"Desapensação deste do PL nº 13, de 2020, proposição principal, em face da aprovação da matéria, em Plenário, na forma da Subemenda Substitutiva Global ao Projeto de Lei nº 13, de 2020, adotada pelo relator da Comissão de Ciência, Tecnologia e Inovação (Sessão Deliberativa Extraordinária de 19/6/2024 - 13h55 - 121ª Sessão).","id":"2420536","law":false,"r":"c"},{"t":"PDL","n":"30","y":"2024","e":"Susta, parcialmente, a Resolução 23.732 de 27 de fevereiro de 2024 do Tribunal Superior Eleitoral, que dispõe sobre propaganda eleitoral, utilização e geração do horário gratuito e condutas ilícitas em campanha eleitoral, especificamente os artigos 9º-D, 9º-E, 9º-F e 9ª-H incluídos pelo art. 1º da Resolução.","d":"2024-03-05","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2025-03-21","ds":"Recebimento pela CCJC, apensado ao PDL-25/2024","id":"2419264","law":false,"r":"c"},{"t":"PDL","n":"24","y":"2024","e":"Este Decreto Legislativo susta os efeitos da Nota Técnica Conjunta n° 2/2024-SAPS/SAES/MS.","d":"2024-02-29","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2024-04-19","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 20/04/2024.","id":"2419066","law":false,"r":"c"},{"t":"PL","n":"214","y":"2024","e":"Institui o Dia Nacional dos Presos Políticos.","d":"2024-02-07","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2024-02-26","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 27/02/2024 PAG 130","id":"2417644","law":false,"r":"c"},{"t":"PL","n":"5793","y":"2023","e":"Altera os artigos 359-L, 359-M e 359-T da Parte Especial do Decreto-lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), bem como o art. 79 do  Decreto-Lei nº 3.689, de 3 de outubro de 1941 (Código de Processo Penal), e dá outras providências.","d":"2023-11-30","o":"approved_with_another_bill","s":"Arquivada","tr":"Prejudicialidade (Plenário)","u":"2025-12-09","ds":"Matéria aprovada na forma do Substitutivo ao Projeto de Lei nº 2.162, de 2023, adotado pelo relator da Comissão Especial (Sessão Deliberativa Extraordinária Presencial de 09/12/2025 - 19:00 - 278ª Sessão). Esta proposição fica prejudicada, na forma do art. 191 do RICD.","id":"2408580","law":false,"r":"c"},{"t":"PDL","n":"392","y":"2023","e":"Susta o Decreto nº 11.764, de 31 de outubro de 2023, que altera a Tabela de Incidência do Imposto sobre Produtos Industrializados - TIPI, aprovada pelo Decreto nº 11.158, de 29 de julho de 2022.","d":"2023-11-01","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2023-11-07","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 08/11/2023.","id":"2401109","law":false,"r":"m"},{"t":"PL","n":"5021","y":"2023","e":"Institui a Lista de Organizações Terroristas, altera a Lei nº 13.260, de 16 de março de 2016, e dá outras providências.","d":"2023-10-17","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificação de Apensação","u":"2026-07-07","ds":"Apensação da proposição PL 2730/2026 à proposição PL 972/2024.","id":"2396351","law":false,"r":"c"},{"t":"PL","n":"4789","y":"2023","e":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 - Código Penal, a Lei nº 8.069, de 13 de julho de 1990 - Estatuto da Criança e do Adolescente, a Lei nº 8.072, de 25 de julho de 1990 - Lei de Crimes Hediondos, a Lei nº 7.210, de 11 de julho de 1984 - Lei de Execução Penal, e o Decreto Lei nº 3.689, de 3 de outubro de 1941 - Código de Processo Penal, para recrudescer o tratamento penal destinado aos crimes sexuais contra crianças e adolescentes, visando prevenir e coibir o incentivo à pedofilia.","d":"2023-10-03","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2026-05-21","ds":"Parecer do Relator, Dep. Filipe Martins (PL-TO), pela aprovação do PL 4789/23, do PLs 20/24,1978/24, 3920/25, 4061/25, e 1201/26, apensados, com substitutivo.","id":"2392485","law":false,"r":"c"},{"t":"PL","n":"4646","y":"2023","e":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), e a Lei nº 8.072, de 25 de julho de 1990 (Lei dos Crimes Hediondos), para aumentar a pena para o crime de tráfico de pessoas, revogar a causa de diminuição de pena prevista e incluir este crime no rol de crimes hediondos.","d":"2023-09-25","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificação de Apensação","u":"2026-03-31","ds":"Apensação do PL 875/2026 a esta proposição.","id":"2390232","law":false,"r":"m"},{"t":"PL","n":"4203","y":"2023","e":"Altera a Lei nº 13.146, de 6 de julho de 2015, que dispõe sobre “Lei Brasileira de Inclusão da Pessoa com Deficiência (Estatuto da Pessoa com Deficiência)”, a fim de acrescentar causa de aumento de pena em caso de discriminação de pessoa com deficiência, cometido por professores em razão de seu exercício.","d":"2023-08-29","o":"status_not_published","s":"","tr":"Notificacao para Publicação Intermediária","u":"2025-04-29","ds":"Designado Relator, Dep. Diego Garcia (REPUBLIC-PR), para o PL 1600/2023, ao qual esta proposição está apensada.","id":"2383605","law":false,"r":"m"},{"t":"PL","n":"4062","y":"2023","e":"Benefício Especial para Crianças em Tratamento de Hemodiálise.","d":"2023-08-22","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-07-15","ds":"Designada Relatora, Dep. Rogéria Santos (REPUBLIC-BA).","id":"2381565","law":false,"r":"c"},{"t":"PL","n":"4061","y":"2023","e":"Altera a Lei nº 12.764, de 27 de dezembro de 2012, que institui a Política Nacional de Proteção dos Direitos da Pessoa com Transtorno do Espectro Autista, e estabelece prazo para o diagnóstico de Transtorno do Espectro Autista pelo Poder Público e dá outras providências.","d":"2023-08-22","o":"in_progress","s":"Pronta para Pauta","tr":"Retirada de Pauta","u":"2024-10-30","ds":"Aprovado o Requerimento de Retirada de Pauta do Deputado Flávio Nogueira.","id":"2381563","law":false,"r":"c"},{"t":"PDL","n":"262","y":"2023","e":"Susta a Resolução CONAC-MPOR nº 1, de 10 agosto de 2023.","d":"2023-08-16","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2024-05-22","ds":"Designado Relator, Dep. Gutemberg Reis (MDB-RJ)","id":"2379900","law":false,"r":"c"},{"t":"PL","n":"3913","y":"2023","e":"Altera as Leis nº 8.112, de 11 de dezembro de 1990; nº 9.394, de 20 de dezembro de 1996 e nº 11.096, de 13 de janeiro de 2005, para determinar a realização de exame toxicológico para ingresso e permanência em cargos públicos; para ingresso em instituições públicas de ensino superior ou profissional; e para manutenção de bolsa de estudo paga pelo Administração Pública.","d":"2023-08-15","o":"in_progress","s":"Tramitando em Conjunto","tr":"Apresentação de Requerimento","u":"2025-06-18","ds":"Apresentação do REQ n. 2360/2025 (Requerimento de Redistribuição), pelo Comissão de Trabalho, que \"Requeiro, nos termos dos arts. 32, XVIII; XXX, a, b, c, e seu parágrafo único; 139, I e II, “a” e 141 do Regimento Interno, a revisão do despacho aposto para os seguintes Projetos de Lei que seguem atualmente apensados ao Projeto de Lei nº 5.431/2016 ..\".","id":"2379208","law":false,"r":"c"},{"t":"PEC","n":"34","y":"2023","e":"Inclui dispositivos nos artigos 3º e 5º da Constituição da República Federativa do Brasil, estabelecendo o combate às drogas ilícitas como princípio fundamental e vedando expressamente a descriminalização do tráfico e a legalização de novas drogas recreativas.","d":"2023-08-09","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Saída de Relator(a) da Comissão - Com Parecer Apresentado","u":"2026-02-10","ds":"(Instalação da Comissão) A Relatora, Dep. Caroline de Toni, não integrava a Comissão na data da instalação (deixou de ser membro em 31/01/2026)","id":"2377463","law":false,"r":"c"},{"t":"PDL","n":"214","y":"2023","e":"Susta o Decreto nº 11.629, de 2023, nos termos do art. 49, V da Constituição Federal.","d":"2023-08-08","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-04-15","ds":"Designado Relator, Dep. Rubens Otoni (PT-GO).","id":"2376477","law":false,"r":"c"},{"t":"PDL","n":"209","y":"2023","e":"Susta os efeitos da Resolução nº 510, de 26 de junho de 2023, do Conselho Nacional de Justiça, que “regulamenta a criação, no âmbito do Conselho Nacional de Justiça e dos Tribunais, respectivamente, da Comissão Nacional de Soluções Fundiárias e das Comissões Regionais de Soluções Fundiárias, institui diretrizes para a realização de visitas técnicas nas áreas objeto de litígio possessório e estabelece protocolos para o tratamento das ações que envolvam despejos ou reintegrações de posse em imóveis de moradia coletiva ou de área produtiva de populações vulneráveis”.","d":"2023-08-03","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2025-03-14","ds":"Recebimento pela CCJC, apensado ao PDL-182/2023","id":"2375447","law":false,"r":"c"},{"t":"PDL","n":"204","y":"2023","e":"Susta parte dos efeitos do DECRETO Nº 6.286, DE 5 DE DEZEMBRO DE 2007, que institui o Programa Saúde na Escola - PSE, e dá outras providências.","d":"2023-08-01","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2025-11-05","ds":"Parecer da Relatora, Dep. Ana Paula Lima (PT-SC), pela rejeição.","id":"2374905","law":false,"r":"c"},{"t":"PDL","n":"198","y":"2023","e":"Susta os efeitos da Resolução nº 715, de 20 de julho de 2023, do Conselho Nacional de Saúde, que trata das “orientações estratégicas para o Plano Plurianual (PPA) e para o Plano Nacional de Saúde (PNS) 2024-2027”.","d":"2023-07-28","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2023-09-28","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 29/09/2023.","id":"2374503","law":false,"r":"c"},{"t":"PDL","n":"189","y":"2023","e":"Susta o Decreto nº 11.615, de 21 de julho de 2023, que regulamenta a Lei nº 10.826, de 22 de dezembro de 2003, para estabelecer regras e procedimentos relativos à aquisição, ao registro, à posse, ao porte, ao cadastro e à comercialização nacional de armas de fogo, munições e acessórios, disciplinar as atividades de caça excepcional, de caça de subsistência, de tiro desportivo e de colecionamento de armas de fogo, munições e acessórios, disciplinar o funcionamento das entidades de tiro desportivo e dispor sobre a estruturação do Sistema Nacional de Armas - Sinarm.","d":"2023-07-22","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2025-04-14","ds":"Devolvido ao Relator, Dep. Delegado Paulo Bilynskyj (PL-SP), para o PDL 3/2023, ao qual esta proposição está apensada.","id":"2374340","law":false,"r":"c"},{"t":"PL","n":"3556","y":"2023","e":"Dispõe sobre o conflito de interesses entre os beneficiários do Programa Nacional de Apoio à Cultura (Pronac), instituído pela Lei nº 8.313 de 23 de Dezembro de 1991 e da Política Nacional Aldir Blanc de Fomento à Cultura, instituída Lei nº 14.399, de 8 de julho de 2022 e impedimentos posteriores.","d":"2023-07-13","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2024-04-23","ds":"Encaminhada à publicação. Parecer da Comissão de Cultura Publicado em avulso e no DCD de 24/04/2024 PAG 2404, Letra A.","id":"2374031","law":false,"r":"m"},{"t":"PL","n":"3462","y":"2023","e":"Institui o Dia Nacional de Conscientização sobre a Síndrome de Edwards.","d":"2023-07-06","o":"in_progress","s":"Aguardando Designação - Aguardando Devolução de Relator(a) que deixou de ser Membro","tr":"Saída de Relator(a) da Comissão - Sem Parecer Apresentado","u":"2026-02-04","ds":"(Instalação da Comissão) O Relator, Dep. Dr. Fernando Máximo, não integrava a Comissão na data da instalação (deixou de ser membro em 31/01/2026)","id":"2373036","law":false,"r":"c"},{"t":"PLP","n":"141","y":"2023","e":"Altera o inciso XIV do artigo 22, da Lei Complementar nº 64, de 18 de maio de 1990, para determinar que a sanção de inelegibilidade para as eleições a se realizarem seja nos 2 (dois) anos subsequentes à eleição.","d":"2023-07-04","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2025-06-11","ds":"Deferido o REQ 678/2025.","id":"2372482","law":false,"r":"c"},{"t":"PL","n":"3317","y":"2023","e":"Concede anistia aos condenados por ilícitos cíveis eleitorais ou declarados inelegíveis do período de 2 de outubro 2016 até a data de entrada em vigor desta lei, na forma que especifica.","d":"2023-06-30","o":"prejudged","s":"Arquivada","tr":"Desapensação","u":"2025-12-09","ds":"Desapensação deste do PL nº 2.162, de 2023, principal, em face da aprovação, em Plenário, do Substitutivo ao Projeto de Lei nº 2.162, de 2023, adotado pelo relator da Comissão Especial. (Sessão Deliberativa Extraordinária Presencial de 09/12/2025 - 19:00 - 278ª Sessão)","id":"2372030","law":false,"r":"c"},{"t":"PL","n":"3175","y":"2023","e":"Torna obrigatória a existência de um plano de contingência e protocolos de segurança preestabelecidos na rede de ensino público e privado de educação básica e de estabelecimentos de recreação infantil em caso de ataques externos ou internos contra a integridade e vida do corpo discente, docente e profissionais que atuam nesses estabelecimentos e dá outras providências.","d":"2023-06-20","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2024-12-09","ds":"Designada Relatora, Dep. Duda Salabert (PDT-MG), para o PL 5343/2019, ao qual esta proposição está apensada.","id":"2370578","law":false,"r":"m"},{"t":"PL","n":"3142","y":"2023","e":"Altera o Código Penal, para dispor sobre a tipificação do crime de permissão de ingresso de ditador em território nacional.","d":"2023-06-19","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2024-10-07","ds":"Parecer da Relatora, Dep. Julia Zanatta (PL-SC), pela constitucionalidade, juridicidade, técnica legislativa e, no mérito, pela aprovação.","id":"2370152","law":false,"r":"c"},{"t":"PL","n":"3127","y":"2023","e":"Estabelece a vedação à indicação de Ministros de Estado em cargos de representação que auferem remuneração, gratificações de presença ou verbas de representação, para participação em Conselhos de Administração e Fiscal, ou em órgãos equivalentes, de pessoas jurídicas sob controle direto ou indireto da União.","d":"2023-06-16","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento - Relator(a) (Sem Manifestação)","u":"2026-05-26","ds":"Devolvida pelo Relator sem Manifestação.","id":"2369984","law":false,"r":"c"},{"t":"PL","n":"3022","y":"2023","e":"Altera a Lei nº 8.069, de 31 de julho de 1990, Estatuto da Criança e do Adolescente – ECA, para tipificar os crimes relativos ao trânsito e a permanência de menores de 18 anos, em eventos que promovam ilicitude; comportamento impróprio para sua faixa etária; insalubridade; situação degradante, abordagem erótica, sexualização infantil e que exerçam influência sobre a sexualidade natural do menor e dá outras providências.","d":"2023-06-13","o":"in_progress","s":"Aguardando Definição Encaminhamento","tr":"Apensação","u":"2025-11-06","ds":"Apensação da proposição PL-4564/2025 à proposição PL-5421/2023.","id":"2368686","law":false,"r":"m"},{"t":"PL","n":"2847","y":"2023","e":"Tipifica como crime tentado os atos preparatórios que incidam na Invasão de Domicílio com fins de subtração na modalidade de Tentativa de Roubo.","d":"2023-05-30","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2023-07-11","ds":"Recebimento pela CCJC.","id":"2366152","law":false,"r":"m"},{"t":"PL","n":"2568","y":"2023","e":"Veda a utilização de dinheiro público em quaisquer eventos e serviços que promovam a erotização precoce ou estimulem a sexualização de crianças e adolescentes.","d":"2023-05-15","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificação de Apensação","u":"2026-07-08","ds":"Apensação do PL 2654/2026 a esta proposição.","id":"2362236","law":false,"r":"c"},{"t":"PL","n":"2501","y":"2023","e":"Dispõe sobre a criação do crime de censura e confisco de plataforma na lei 13.869 de 5 de setembro de 2019, que dispõe sobre os crimes de abuso de autoridade, e adiciona o crime de censura na lei 1.079 de 10 de abril de 1950, que dispõe sobre os crimes de responsabilidade, e dá outras providências.","d":"2023-05-10","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2025-10-15","ds":"Designado Relator, Dep. Pr. Marco Feliciano (PL-SP), para o PL 2782/2022, ao qual esta proposição está apensada.","id":"2361794","law":false,"r":"c"},{"t":"PL","n":"1869","y":"2023","e":"Acrescenta dispositivo a Lei no 8.069, de 13 de julho de 1990, que “Dispõe sobre o Estatuto da Criança e do adolescente e dá ou providências”, para dispor sobre a permissão de inspeção de malas, bolsas, mochilas e\nmaletas dos estudantes das redes públicas e privadas de ensino, quando do ingresso e permanência nesses estabelecimentos.","d":"2023-04-13","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2024-12-09","ds":"Designada Relatora, Dep. Duda Salabert (PDT-MG), para o PL 5343/2019, ao qual esta proposição está apensada.","id":"2356215","law":false,"r":"m"},{"t":"PEC","n":"5","y":"2023","e":"Acrescenta § 4º-A ao art. 150 da Constituição Federal, para dispor sobre a imunidade tributária de que tratam as suas alíneas “b” e “c” do inciso VI.","d":"2023-03-15","o":"approved","s":"Aguardando Apreciação pelo Senado Federal","tr":"Expedição de Documento","u":"2026-06-01","ds":"Remessa ao Senado Federal por meio do Of. nº 143/2026/SGM-P.","id":"2351506","law":false,"r":"c"},{"t":"PL","n":"804","y":"2023","e":"Altera a Lei nº 8.080 de 1990, para determinar a criação de listas de espera para realização de cirurgias eletivas no âmbito do Sistema Único de Saúde (SUS).","d":"2023-03-02","o":"prejudged","s":"Arquivada","tr":"Desapensação","u":"2024-02-21","ds":"Desapensação deste do PL nº 10.106, de 2018, proposição principal, em face da aprovação da matéria, em Plenário, na forma da Subemenda Substitutiva Global ao Projeto de Lei nº 10.106, de 2018, adotada pelo relator da Comissão de Saúde (Sessão Deliberativa Extraordinária de 21/02/2024 - 13h55 - 5ª Sessão).","id":"2349847","law":false,"r":"c"},{"t":"PL","n":"802","y":"2023","e":"Institui o Fundo Nacional de Recuperação de Ativos e Combate à Corrupção – FNRACC, e disciplina a destinação dos recursos arrecadados.","d":"2023-03-02","o":"prejudged","s":"Arquivada","tr":"Arquivamento","u":"2023-08-15","ds":"Declarado prejudicado em face da aprovação em Plenário da Subemenda Substitutiva Global ao Projeto de Lei nº 3.394, de 2015, adotada pela Relatora da Comissão de Administração e Serviço Público (Sessão Deliberativa Extraordinária de 15/8/2023 - 13h55 - 141ª Sessão).","id":"2349845","law":false,"r":"c"},{"t":"PL","n":"721","y":"2023","e":"Institui o Dia Nacional do segmento Gamer e do eSports no Brasil.","d":"2023-02-28","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2023-04-28","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 29/04/2023 PAG 320","id":"2349520","law":false,"r":"m"},{"t":"PL","n":"719","y":"2023","e":"Dispõe sobre a proibição de execução de músicas com letras que façam apologia ao crime, ao uso de drogas e/ou que expressem conteúdos sexuais, nas Instituições Escolares Públicas e Privadas na rede de ensino de todo território nacional.","d":"2023-02-28","o":"in_progress","s":"Tramitando em Conjunto","tr":"Apensação","u":"2025-11-06","ds":"Apensação da proposição PL-4859/2025 à proposição PL-719/2023.","id":"2349518","law":false,"r":"m"},{"t":"PDL","n":"47","y":"2023","e":"Susta os efeitos da PORTARIA N° 299, de 30 de janeiro de 2023, que dispõe sobre o cadastro de armas no Sistema Nacional de Armas- Sinarm, nos termos do Decreto n° 11.366, de 1° de janeiro de 2023.","d":"2023-02-16","o":"status_not_published","s":"","tr":"Notificações","u":"2025-04-14","ds":"Devolvido ao Relator, Dep. Delegado Paulo Bilynskyj (PL-SP), para o PDL 3/2023, ao qual esta proposição está apensada.","id":"2348964","law":false,"r":"c"},{"t":"PL","n":"269","y":"2023","e":"Dispõe sobre a proibição de bloqueio puberal hormonal em crianças e adolescentes em processo transexualizador e de terapia hormonal e cirurgia de redesignação sexual, respectivamente a menores de 18 e 21 anos.","d":"2023-02-03","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2025-12-18","ds":"Designada Relatora, Dep. Talíria Petrone (PSOL-RJ), para o PL 3419/2019, ao qual esta proposição está apensada.","id":"2347069","law":false,"r":"m"},{"t":"PL","n":"215","y":"2023","e":"Altera o Decreto-Lei nº. 2.848, de 7 de dezembro de 1940 - Código Penal, para tornar homicídio qualificado o crime praticado contra mais de um membro da mesma família (familicídio), entre outras disposições.","d":"2023-02-02","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2023-06-01","ds":"Parecer do Relator, Dep. José Medeiros (PL-MT), pela constitucionalidade, juridicidade, técnica legislativa e, no mérito, pela aprovação, com substitutivo.","id":"2346963","law":false,"r":"c"},{"t":"PDL","n":"3","y":"2023","e":"Susta o Decreto nº 11.366, de 1º de janeiro 2023, que limita o registro e a aquisição de armas de fogos.","d":"2023-02-02","o":"in_progress","s":"Aguardando Parecer","tr":"Devolução ao(à) Relator(a)","u":"2025-04-14","ds":"Devolvido ao Relator, Dep. Delegado Paulo Bilynskyj (PL-SP)","id":"2345680","law":false,"r":"c"}];
